package api_test

// Integration tests of the decision routes (T-026) through the whole
// stack: proposals generated by the job loop over the fake provider, then
// approved or rejected over HTTP as the plain API login (TEST-005,
// TEST-006, TEST-007, TEST-009 for decisions). Without
// GEMINUS_TEST_DATABASE_URL they skip (NOT RUN).

import (
	"strings"
	"testing"

	"github.com/kcl1104/geminus/internal/ai/provider"
	"github.com/kcl1104/geminus/internal/proposals"
	"github.com/kcl1104/geminus/internal/tenant"
)

func (e *env) decide(subject, org, id, action, key, body string) resp {
	h := map[string]string{}
	if key != "" {
		h["Idempotency-Key"] = key
	}
	return e.do("POST", "/v1/ai-proposals/"+id+"/"+action, subject, org, h, body)
}

// readyOver queues a proposal over HTTP with a scripted answer and runs the
// loop until it is ready.
func (e *proposalEnv) readyOver(t *testing.T, modelID, base, mode, intent, answer string) proposalView {
	t.Helper()
	editor := e.a.Members[tenant.Editor]
	e.fake.Script(provider.RoleModeler, intent, []byte(answer))
	r := e.propose(editor.Subject, e.a.ID, modelID, "key-"+t.Name()+"-"+strings.ReplaceAll(intent, " ", "-"), proposalBody(base, mode, intent))
	if r.status != 202 {
		t.Fatalf("propose: %d %s", r.status, r.body)
	}
	p := e.generated(t, editor.Subject, e.a.ID, decode[proposals.Accepted](t, r).ProposalID)
	if p.Status != "ready" {
		t.Fatalf("not ready: %+v", p)
	}
	return p
}

type approvalBody struct {
	ProposalID     string `json:"proposal_id"`
	Status         string `json:"status"`
	Mode           string `json:"mode"`
	NewVersionID   string `json:"new_version_id"`
	ScenarioID     string `json:"scenario_id"`
	Version        int64  `json:"version"`
	PatchHash      string `json:"patch_hash"`
	DraftOutOfDate bool   `json:"draft_out_of_date"`
}

// The closed loop of AI Alpha (IMPLEMENTATION_PLAN): intent, ready
// proposal, a person's approval, exactly one new version, the draft moved
// to it; a scenario approval with no version and no run; a rejection that
// changes nothing; every answer in its schema.
func TestApprovalClosedLoop(t *testing.T) {
	e := setupProposals(t)
	editor, viewer := e.a.Members[tenant.Editor], e.a.Members[tenant.Viewer]
	m := e.newModel(t)
	p := e.readyOver(t, m.ID, m.LatestVersion.ID, "edit", "Raise the CI runners to 6.", raiseCI)
	r := e.decide(editor.Subject, e.a.ID, p.ProposalID, "approve", "appr-loop-0001",
		`{"expected_base_version_id":"`+m.LatestVersion.ID+`","comment":"Reviewed."}`)
	if r.status != 201 {
		t.Fatalf("approve: %d %s", r.status, r.body)
	}
	valid(t, r, "http.schema.json#/$defs/Approval")
	a := decode[approvalBody](t, r)
	if a.Mode != "edit" || a.Version != 2 || a.DraftOutOfDate || a.PatchHash != *p.PatchHash {
		t.Errorf("%s", r.body)
	}
	got := e.proposal(t, viewer.Subject, e.a.ID, p.ProposalID)
	if got.Status != "approved" {
		t.Errorf("%+v", got)
	}
	versions := e.do("GET", "/v1/models/"+m.ID+"/versions", viewer.Subject, e.a.ID, nil, "")
	valid(t, versions, "http.schema.json#/$defs/Versions")
	if !strings.Contains(string(versions.body), `"id":"`+a.NewVersionID+`"`) || !strings.Contains(string(versions.body), `"comment":"Reviewed."`) {
		t.Errorf("the new version is not listed with its comment: %s", versions.body)
	}
	draft := e.do("GET", "/v1/models/"+m.ID+"/draft", viewer.Subject, e.a.ID, nil, "")
	if draft.header.Get("ETag") != etag(2) || !strings.Contains(string(draft.body), `"base_version_id":"`+a.NewVersionID+`"`) {
		t.Errorf("the clean draft did not move: %s %s", draft.header.Get("ETag"), draft.body)
	}
	// The same key replays the answer.
	if again := e.decide(editor.Subject, e.a.ID, p.ProposalID, "approve", "appr-loop-0001",
		`{"expected_base_version_id":"`+m.LatestVersion.ID+`","comment":"Reviewed."}`); again.status != 201 || string(again.body) != string(r.body) {
		t.Errorf("replay: %d %s", again.status, again.body)
	}

	// A scenario on the new latest version: one scenario, no version, no run.
	s := e.readyOver(t, m.ID, a.NewVersionID, "scenario", "What if there were 8 runners?",
		`{"status":"proposed","summary":"Try 8 CI runners.","assumptions":[],"risk_level":"low","confidence":0.8,`+
			`"changes":[{"op":"test","path":"/resources/1/id","value":"ci_runner"},{"op":"replace","path":"/resources/1/capacity","value":8}],`+
			`"expected_effects":["Waiting may fall; a simulation will tell."],"requires_confirmation":true}`)
	versionsBefore := e.count(`SELECT count(*) FROM twin.model_versions WHERE model_id=$1`, m.ID)
	r = e.decide(editor.Subject, e.a.ID, s.ProposalID, "approve", "appr-loop-0002", `{"expected_base_version_id":"`+a.NewVersionID+`"}`)
	if r.status != 201 {
		t.Fatalf("approve the scenario: %d %s", r.status, r.body)
	}
	valid(t, r, "http.schema.json#/$defs/Approval")
	sa := decode[approvalBody](t, r)
	if sa.Mode != "scenario" || sa.ScenarioID == "" || sa.NewVersionID != "" {
		t.Errorf("%s", r.body)
	}
	if n := e.count(`SELECT count(*) FROM twin.model_versions WHERE model_id=$1`, m.ID); n != versionsBefore {
		t.Errorf("a scenario approval made %d versions out of %d", n, versionsBefore)
	}
	if n := e.count(`SELECT count(*) FROM twin.jobs WHERE organization_id=$1 AND type='simulation'`, e.a.ID); n != 0 {
		t.Errorf("a scenario approval queued %d runs", n)
	}
	if n := e.count(`SELECT count(*) FROM twin.scenarios WHERE id=$1 AND source_proposal_id=$2 AND base_version_id=$3 AND name='Try 8 CI runners.'`,
		sa.ScenarioID, s.ProposalID, a.NewVersionID); n != 1 {
		t.Errorf("%d scenarios", n)
	}

	// A rejection: the proposal as getProposal shows it, nothing else.
	j := e.readyOver(t, m.ID, a.NewVersionID, "edit", "Lower the runners.", lowerRunners)
	before := e.do("GET", "/v1/models/"+m.ID+"/draft", editor.Subject, e.a.ID, nil, "")
	r = e.decide(editor.Subject, e.a.ID, j.ProposalID, "reject", "appr-loop-0003", `{"comment":"No."}`)
	if r.status != 200 {
		t.Fatalf("reject: %d %s", r.status, r.body)
	}
	valid(t, r, "proposal.schema.json")
	if !strings.Contains(string(r.body), `"status":"rejected"`) || !strings.Contains(string(r.body), `"decision_comment":"No."`) {
		t.Errorf("%s", r.body)
	}
	after := e.do("GET", "/v1/models/"+m.ID+"/draft", editor.Subject, e.a.ID, nil, "")
	if string(before.body) != string(after.body) || before.header.Get("ETag") != after.header.Get("ETag") {
		t.Errorf("a rejection changed the draft")
	}
	// Reject takes an empty body too.
	k := e.readyOver(t, m.ID, a.NewVersionID, "edit", "Lower them again.", lowerRunners)
	if r := e.decide(editor.Subject, e.a.ID, k.ProposalID, "reject", "appr-loop-0004", `{}`); r.status != 200 {
		t.Errorf("reject {}: %d %s", r.status, r.body)
	}
}

// lowerRunners is raiseCI's opposite (medium risk: a lower capacity, D-016).
const lowerRunners = `{"status":"proposed","summary":"Lower the CI runner capacity.","assumptions":[],"risk_level":"low","confidence":0.9,` +
	`"changes":[{"op":"test","path":"/resources/1/id","value":"ci_runner"},{"op":"replace","path":"/resources/1/capacity","value":2}],` +
	`"expected_effects":["Waiting may rise; a simulation will tell."],"requires_confirmation":true}`

// TEST-009 and the error contract: who may decide, and every refusal in
// the error envelope with its code, JSON Pointer and request ID.
func TestApprovalRefusals(t *testing.T) {
	e := setupProposals(t)
	owner, editor, viewer := e.a.Members[tenant.Owner], e.a.Members[tenant.Editor], e.a.Members[tenant.Viewer]
	stranger := e.b.Members[tenant.Owner]
	m := e.newModel(t)
	p := e.readyOver(t, m.ID, m.LatestVersion.ID, "edit", "Raise the CI runners to 6.", raiseCI)
	approve := `{"expected_base_version_id":"` + m.LatestVersion.ID + `"}`
	for _, c := range []struct {
		name, subject, org, id, action, key, body string
		headers                                   map[string]string
		status                                    int
		code, path                                string
	}{
		{"no token", "", e.a.ID, p.ProposalID, "approve", "appr-ref-0001", approve, nil, 401, "UNAUTHENTICATED", ""},
		{"a viewer approves", viewer.Subject, e.a.ID, p.ProposalID, "approve", "appr-ref-0002", approve, nil, 403, "FORBIDDEN", ""},
		{"a viewer rejects", viewer.Subject, e.a.ID, p.ProposalID, "reject", "appr-ref-0003", `{}`, nil, 403, "FORBIDDEN", ""},
		{"another organization", stranger.Subject, e.b.ID, p.ProposalID, "approve", "appr-ref-0004", approve, nil, 404, "NOT_FOUND", ""},
		{"a non-member choosing it", stranger.Subject, e.a.ID, p.ProposalID, "reject", "appr-ref-0005", `{}`, nil, 404, "NOT_FOUND", ""},
		{"a bad ID", editor.Subject, e.a.ID, "aip_x", "approve", "appr-ref-0006", approve, nil, 400, "INVALID_REQUEST", ""},
		{"no key", editor.Subject, e.a.ID, p.ProposalID, "approve", "", approve, nil, 400, "IDEMPOTENCY_KEY_REQUIRED", ""},
		{"bad JSON", editor.Subject, e.a.ID, p.ProposalID, "approve", "appr-ref-0007", `{"expected_base_version_id":`, nil, 400, "INVALID_REQUEST", ""},
		{"no base", editor.Subject, e.a.ID, p.ProposalID, "approve", "appr-ref-0008", `{"comment":"x"}`, nil, 422, "REQUEST_VALIDATION_FAILED", ""},
		{"an approver in the body", editor.Subject, e.a.ID, p.ProposalID, "approve", "appr-ref-0009",
			`{"expected_base_version_id":"` + m.LatestVersion.ID + `","approved_by":"` + owner.UserID + `"}`, nil, 422, "REQUEST_VALIDATION_FAILED", ""},
		{"a long comment", editor.Subject, e.a.ID, p.ProposalID, "reject", "appr-ref-0010", `{"comment":"` + strings.Repeat("x", 2001) + `"}`, nil, 422, "REQUEST_VALIDATION_FAILED", "/comment"},
		{"a base in a rejection", editor.Subject, e.a.ID, p.ProposalID, "reject", "appr-ref-0011", approve, nil, 422, "REQUEST_VALIDATION_FAILED", ""},
		{"another media type", editor.Subject, e.a.ID, p.ProposalID, "approve", "appr-ref-0012", approve, map[string]string{"Content-Type": "text/plain"}, 415, "UNSUPPORTED_MEDIA_TYPE", ""},
		{"another base", editor.Subject, e.a.ID, p.ProposalID, "approve", "appr-ref-0013", `{"expected_base_version_id":"mv_01M4YDQK00FRYWV7GS7X1QCXZR"}`, nil, 409, "MODEL_VERSION_CONFLICT", "/expected_base_version_id"},
	} {
		h := map[string]string{}
		for k, v := range c.headers {
			h[k] = v
		}
		if c.key != "" {
			h["Idempotency-Key"] = c.key
		}
		r := e.do("POST", "/v1/ai-proposals/"+c.id+"/"+c.action, c.subject, c.org, h, c.body)
		if r.status != c.status || code(t, r) != c.code {
			t.Errorf("%s: %d %s", c.name, r.status, r.body)
			continue
		}
		if c.path != "" && !strings.Contains(string(r.body), `"path":"`+c.path+`"`) {
			t.Errorf("%s: no detail at %s: %s", c.name, c.path, r.body)
		}
	}
	if got := e.proposal(t, viewer.Subject, e.a.ID, p.ProposalID); got.Status != "ready" {
		t.Fatalf("a refused decision moved the proposal to %s", got.Status)
	}

	// Decided: 409 PROPOSAL_ALREADY_DECIDED with a new key (D-030).
	if r := e.decide(owner.Subject, e.a.ID, p.ProposalID, "approve", "appr-ref-0100", approve); r.status != 201 {
		t.Fatalf("approve: %d %s", r.status, r.body)
	}
	for _, c := range []struct{ action, key, body string }{{"approve", "appr-ref-0101", approve}, {"reject", "appr-ref-0102", `{}`}} {
		if r := e.decide(editor.Subject, e.a.ID, p.ProposalID, c.action, c.key, c.body); r.status != 409 || code(t, r) != "PROPOSAL_ALREADY_DECIDED" {
			t.Errorf("%s an approved proposal: %d %s", c.action, r.status, r.body)
		}
	}
	// The base moved: of two proposals on version 2, the one approved
	// second is conflicted.
	base2 := e.latest(t, m.ID)
	q := e.readyOver(t, m.ID, base2, "edit", "Lower the runners.", lowerRunners)
	stale := e.readyOver(t, m.ID, base2, "edit", "Lower them again.", lowerRunners)
	if r := e.decide(owner.Subject, e.a.ID, q.ProposalID, "approve", "appr-ref-0200", `{"expected_base_version_id":"`+base2+`"}`); r.status != 201 {
		t.Fatalf("approve: %d %s", r.status, r.body)
	}
	r := e.decide(editor.Subject, e.a.ID, stale.ProposalID, "approve", "appr-ref-0201", `{"expected_base_version_id":"`+base2+`"}`)
	if r.status != 409 || code(t, r) != "MODEL_VERSION_CONFLICT" || !strings.Contains(string(r.body), `"path":"/expected_base_version_id"`) {
		t.Errorf("a moved base: %d %s", r.status, r.body)
	}
	if got := e.proposal(t, viewer.Subject, e.a.ID, stale.ProposalID); got.Status != "conflicted" {
		t.Errorf("after a moved base: %s", got.Status)
	}
	// Not ready: a proposal that asks for input cannot be approved.
	asked := e.propose(editor.Subject, e.a.ID, m.ID, "appr-ref-0300", proposalBody(e.latest(t, m.ID), "edit", "Something vague."))
	id := decode[proposals.Accepted](t, asked).ProposalID
	if got := e.generated(t, viewer.Subject, e.a.ID, id); got.Status != "needs_input" {
		t.Fatalf("%+v", got)
	}
	if r := e.decide(editor.Subject, e.a.ID, id, "approve", "appr-ref-0301", `{"expected_base_version_id":"`+e.latest(t, m.ID)+`"}`); r.status != 409 || code(t, r) != "LIFECYCLE_CONFLICT" {
		t.Errorf("approving needs_input: %d %s", r.status, r.body)
	}
}

// latest is the model's latest version over HTTP.
func (e *proposalEnv) latest(t *testing.T, modelID string) string {
	t.Helper()
	r := e.do("GET", "/v1/models/"+modelID, e.a.Members[tenant.Viewer].Subject, e.a.ID, nil, "")
	if r.status != 200 {
		t.Fatalf("%d %s", r.status, r.body)
	}
	return decode[modelSummary](t, r).LatestVersion.ID
}
